from money import split_amount


def test_even_split():
    assert split_amount(90, 3) == [30, 30, 30]


def test_one_part():
    assert split_amount(55, 1) == [55]


def test_leftover_cents_go_to_first_shares():
    assert split_amount(100, 3) == [34, 33, 33]
    assert split_amount(101, 3) == [34, 34, 33]


def test_shares_add_up():
    for total in range(0, 200):
        for parts in range(1, 12):
            shares = split_amount(total, parts)
            assert len(shares) == parts
            assert sum(shares) == total


def test_parts_below_one_raises():
    import pytest
    for parts in (0, -1):
        with pytest.raises(ValueError):
            split_amount(100, parts)

